// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./RoleManager.sol";
import "./DeliveryOrderNFT.sol";
import "./AuditLog.sol";

/// @title HandoverManager
/// @notice Orchestrates the custody chain for delivery orders.
///         Enforced sequence: RESTAURANT → PACKER → DRIVER → RECEIVER → (restaurant completes)
contract HandoverManager {

    RoleManager      public roleManager;
    DeliveryOrderNFT public deliveryOrderNFT;
    AuditLog         public auditLog;

    /// @notice orderId => assigned packer address
    mapping(uint256 => address) public assignedPacker;

    /// @notice orderId => assigned driver address
    mapping(uint256 => address) public assignedDriver;

    event PackerAssigned(uint256 indexed orderId, address indexed packer);
    event HandedToDriver(uint256 indexed orderId, address indexed driver);
    event HandedToReceiver(uint256 indexed orderId, address indexed receiver);
    event ReceiptConfirmed(uint256 indexed orderId, address indexed receiver);
    event ExceptionFlagged(uint256 indexed orderId, address indexed reporter, string note);

    modifier hasRole(RoleManager.Role required) {
        require(
            roleManager.getRole(msg.sender) == required,
            "HandoverManager: wrong role"
        );
        _;
    }

    constructor(
        address _roleManager,
        address _deliveryOrderNFT,
        address _auditLog
    ) {
        roleManager      = RoleManager(_roleManager);
        deliveryOrderNFT = DeliveryOrderNFT(_deliveryOrderNFT);
        auditLog         = AuditLog(_auditLog);
    }

    // -------------------------------------------------------------------------
    // Step 1 — Supervisor assigns a packer to a PENDING order
    // -------------------------------------------------------------------------

    function assignPacker(uint256 orderId, address packerAddr)
        external hasRole(RoleManager.Role.SUPERVISOR)
    {
        require(
            deliveryOrderNFT.getOrderStatus(orderId) == DeliveryOrderNFT.OrderStatus.PENDING,
            "HandoverManager: order must be PENDING"
        );
        roleManager.requireRole(packerAddr, RoleManager.Role.PACKER);

        assignedPacker[orderId] = packerAddr;

        string memory packerName = roleManager.names(packerAddr);
        deliveryOrderNFT.assignPacker(orderId, packerName);

        auditLog.writeEntry(orderId, AuditLog.EntryType.ORDER_ASSIGNED, msg.sender,
            string.concat("Packer assigned: ", packerName));

        emit PackerAssigned(orderId, packerAddr);
    }

    // -------------------------------------------------------------------------
    // Step 2 — Packer hands order to Driver
    // -------------------------------------------------------------------------

    function handoverToDriver(uint256 orderId, address driverAddr)
        external hasRole(RoleManager.Role.PACKER)
    {
        require(assignedPacker[orderId] == msg.sender, "HandoverManager: not the assigned packer");
        require(
            deliveryOrderNFT.getOrderStatus(orderId) == DeliveryOrderNFT.OrderStatus.ASSIGNED,
            "HandoverManager: order must be ASSIGNED"
        );
        roleManager.requireRole(driverAddr, RoleManager.Role.DRIVER);

        assignedDriver[orderId] = driverAddr;

        string memory driverName = roleManager.names(driverAddr);
        deliveryOrderNFT.setDriverName(orderId, driverName);
        deliveryOrderNFT.transferCustody(orderId, driverAddr);

        auditLog.writeEntry(orderId, AuditLog.EntryType.HANDOVER, msg.sender,
            string.concat("Handed to driver: ", driverName));

        emit HandedToDriver(orderId, driverAddr);
    }

    // -------------------------------------------------------------------------
    // Step 3 — Driver hands order to Receiver
    // -------------------------------------------------------------------------

    function handoverToReceiver(uint256 orderId, address receiverAddr)
        external hasRole(RoleManager.Role.DRIVER)
    {
        require(assignedDriver[orderId] == msg.sender, "HandoverManager: not the assigned driver");
        require(
            deliveryOrderNFT.getOrderStatus(orderId) == DeliveryOrderNFT.OrderStatus.IN_TRANSIT,
            "HandoverManager: order must be IN_TRANSIT"
        );
        roleManager.requireRole(receiverAddr, RoleManager.Role.RECEIVER);

        deliveryOrderNFT.transferCustody(orderId, receiverAddr);

        string memory receiverName = roleManager.names(receiverAddr);
        auditLog.writeEntry(orderId, AuditLog.EntryType.HANDOVER, msg.sender,
            string.concat("Handed to receiver: ", receiverName));

        emit HandedToReceiver(orderId, receiverAddr);
    }

    // -------------------------------------------------------------------------
    // Step 4 — Receiver confirms receipt
    // -------------------------------------------------------------------------

    function confirmReceipt(uint256 orderId)
        external hasRole(RoleManager.Role.RECEIVER)
    {
        require(
            deliveryOrderNFT.getOrderStatus(orderId) == DeliveryOrderNFT.OrderStatus.IN_TRANSIT,
            "HandoverManager: order must be IN_TRANSIT"
        );

        DeliveryOrderNFT.Order memory order = deliveryOrderNFT.getOrder(orderId);
        require(order.currentHolder == msg.sender, "HandoverManager: not the current holder");

        deliveryOrderNFT.markDelivered(orderId);

        auditLog.writeEntry(orderId, AuditLog.EntryType.HANDOVER, msg.sender, "Receiver confirmed delivery");

        emit ReceiptConfirmed(orderId, msg.sender);
    }

    // -------------------------------------------------------------------------
    // Exception reporting — PACKER, DRIVER, RECEIVER, or RESTAURANT
    // -------------------------------------------------------------------------

    function reportException(uint256 orderId, string calldata note) external {
        RoleManager.Role callerRole = roleManager.getRole(msg.sender);
        require(
            callerRole == RoleManager.Role.PACKER    ||
            callerRole == RoleManager.Role.DRIVER     ||
            callerRole == RoleManager.Role.RECEIVER   ||
            callerRole == RoleManager.Role.RESTAURANT,
            "HandoverManager: not authorised"
        );

        deliveryOrderNFT.reportException(orderId, msg.sender, note);

        emit ExceptionFlagged(orderId, msg.sender, note);
    }
}

AuditLog.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title AuditLog
/// @notice Append-only log of significant events, written by other contracts.
contract AuditLog {

    enum EntryType {
        ORDER_CREATED,
        ORDER_ASSIGNED,
        HANDOVER,
        EXCEPTION_REPORTED,
        ORDER_COMPLETED
    }

    struct LogEntry {
        EntryType entryType;
        address   actor;
        string    details;
        uint256   timestamp;
    }

    address public admin;

    mapping(address => bool) public authorisedWriters;

    /// @notice orderId => list of log entries for that order
    mapping(uint256 => LogEntry[]) private _entries;

    event EntryWritten(uint256 indexed orderId, EntryType entryType, address indexed actor);

    modifier onlyAdmin() {
        require(msg.sender == admin, "AuditLog: not admin");
        _;
    }

    modifier onlyAuthorised() {
        require(authorisedWriters[msg.sender], "AuditLog: not authorised");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    /// @notice Authorise a contract to write log entries.
    function authoriseWriter(address writer) external onlyAdmin {
        authorisedWriters[writer] = true;
    }

    /// @notice Append a log entry for an order. Only callable by authorised contracts.
    function writeEntry(
        uint256 orderId,
        EntryType entryType,
        address actor,
        string calldata details
    ) external onlyAuthorised {
        _entries[orderId].push(LogEntry({
            entryType: entryType,
            actor:     actor,
            details:   details,
            timestamp: block.timestamp
        }));

        emit EntryWritten(orderId, entryType, actor);
    }

    /// @notice Return all log entries for a given order.
    function getEntriesForOrder(uint256 orderId)
        external
        view
        returns (LogEntry[] memory)
    {
        return _entries[orderId];
    }
}

DeliveryOrderNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./RoleManager.sol";
import "./AuditLog.sol";

/// Each token represents a unique delivery order.
/// Restaurants mint tokens, HandoverManager updates their state.
contract DeliveryOrderNFT {

    enum OrderStatus {
        PENDING,
        ASSIGNED,
        IN_TRANSIT,
        DELIVERED,
        COMPLETED
    }

    struct OrderItem {
        string  name;
        uint256 quantity;
    }

    struct Order {
        uint256     tokenId;
        address     restaurant;
        address     currentHolder;
        OrderStatus status;
        OrderItem[] items;
        string      packerName;
        string      driverName;
        bool        hasException;
        string      exceptionNote;
    }

    RoleManager public roleManager;
    AuditLog    public auditLog;
    address     public handoverManager;
    address     public admin;

    uint256 private _nextTokenId = 1;

    mapping(uint256 => Order) private _orders;

    event OrderMinted(uint256 indexed tokenId, address indexed restaurant);
    event OrderStatusChanged(uint256 indexed tokenId, OrderStatus newStatus);
    event ExceptionReported(uint256 indexed tokenId, string note);
    event OrderCompleted(uint256 indexed tokenId);

    modifier onlyAdmin() {
        require(msg.sender == admin, "DeliveryOrderNFT: not admin");
        _;
    }

    modifier onlyHandoverManager() {
        require(msg.sender == handoverManager, "DeliveryOrderNFT: not HandoverManager");
        _;
    }

    modifier tokenExists(uint256 tokenId) {
        require(_orders[tokenId].restaurant != address(0), "DeliveryOrderNFT: token does not exist");
        _;
    }

    modifier notCompleted(uint256 tokenId) {
        require(_orders[tokenId].status != OrderStatus.COMPLETED, "DeliveryOrderNFT: order is locked");
        _;
    }

    constructor(address _roleManager, address _auditLog) {
        admin       = msg.sender;
        roleManager = RoleManager(_roleManager);
        auditLog    = AuditLog(_auditLog);
    }

    /// @notice Link the HandoverManager after deployment.
    function setHandoverManager(address _handoverManager) external onlyAdmin {
        handoverManager = _handoverManager;
    }

    // -------------------------------------------------------------------------
    // Restaurant: place an order
    // -------------------------------------------------------------------------

    /// @notice Mint a new delivery order token.
    function placeOrder(
        string[] calldata itemNames,
        uint256[] calldata itemQuantities
    ) external returns (uint256 tokenId) {
        roleManager.requireRole(msg.sender, RoleManager.Role.RESTAURANT);
        require(itemNames.length > 0, "DeliveryOrderNFT: no items");
        require(itemNames.length == itemQuantities.length, "DeliveryOrderNFT: array mismatch");

        tokenId = _nextTokenId++;

        Order storage o  = _orders[tokenId];
        o.tokenId        = tokenId;
        o.restaurant     = msg.sender;
        o.currentHolder  = msg.sender;
        o.status         = OrderStatus.PENDING;

        for (uint256 i = 0; i < itemNames.length; i++) {
            o.items.push(OrderItem({ name: itemNames[i], quantity: itemQuantities[i] }));
        }

        auditLog.writeEntry(tokenId, AuditLog.EntryType.ORDER_CREATED, msg.sender, "Order placed");

        emit OrderMinted(tokenId, msg.sender);
    }

    // -------------------------------------------------------------------------
    // HandoverManager-only mutation functions
    // -------------------------------------------------------------------------

    function assignPacker(uint256 tokenId, string calldata packerName)
        external onlyHandoverManager tokenExists(tokenId) notCompleted(tokenId)
    {
        _orders[tokenId].packerName = packerName;
        _orders[tokenId].status = OrderStatus.ASSIGNED;
        emit OrderStatusChanged(tokenId, OrderStatus.ASSIGNED);
    }

    function transferCustody(uint256 tokenId, address newHolder)
        external onlyHandoverManager tokenExists(tokenId) notCompleted(tokenId)
    {
        _orders[tokenId].currentHolder = newHolder;
        _orders[tokenId].status = OrderStatus.IN_TRANSIT;
        emit OrderStatusChanged(tokenId, OrderStatus.IN_TRANSIT);
    }

    function setDriverName(uint256 tokenId, string calldata driverName)
        external onlyHandoverManager tokenExists(tokenId) notCompleted(tokenId)
    {
        _orders[tokenId].driverName = driverName;
    }

    function markDelivered(uint256 tokenId)
        external onlyHandoverManager tokenExists(tokenId) notCompleted(tokenId)
    {
        _orders[tokenId].status = OrderStatus.DELIVERED;
        emit OrderStatusChanged(tokenId, OrderStatus.DELIVERED);
    }

    function reportException(uint256 tokenId, address reporter, string calldata note)
        external onlyHandoverManager tokenExists(tokenId) notCompleted(tokenId)
    {
        _orders[tokenId].hasException  = true;
        _orders[tokenId].exceptionNote = note;

        auditLog.writeEntry(tokenId, AuditLog.EntryType.EXCEPTION_REPORTED, reporter, note);

        emit ExceptionReported(tokenId, note);
    }

    // -------------------------------------------------------------------------
    // Restaurant: complete the order
    // -------------------------------------------------------------------------

    /// @notice Lock the order permanently once delivery is confirmed.
    function completeOrder(uint256 tokenId)
        external tokenExists(tokenId) notCompleted(tokenId)
    {
        Order storage o = _orders[tokenId];
        require(msg.sender == o.restaurant, "DeliveryOrderNFT: only restaurant can complete");
        require(o.status == OrderStatus.DELIVERED, "DeliveryOrderNFT: not yet delivered");

        o.status = OrderStatus.COMPLETED;

        auditLog.writeEntry(tokenId, AuditLog.EntryType.ORDER_COMPLETED, msg.sender, "Order completed and locked");

        emit OrderCompleted(tokenId);
    }

    // -------------------------------------------------------------------------
    // View functions
    // -------------------------------------------------------------------------

    function getOrder(uint256 tokenId) external view tokenExists(tokenId) returns (Order memory) {
        return _orders[tokenId];
    }

    function getOrderStatus(uint256 tokenId) external view tokenExists(tokenId) returns (OrderStatus) {
        return _orders[tokenId].status;
    }

    function totalOrders() external view returns (uint256) {
        return _nextTokenId - 1;
    }
}

RoleManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// Registers stakeholder roles and verifies them for other contracts.
contract RoleManager {

    enum Role {
        NONE,
        RESTAURANT,
        SUPERVISOR,
        PACKER,
        DRIVER,
        RECEIVER
    }

    address public admin;

    mapping(address => Role) public roles;
    mapping(address => string) public names;

    event RoleGranted(address indexed account, Role role, string name);

    modifier onlyAdmin() {
        require(msg.sender == admin, "RoleManager: not admin");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    /// Register a stakeholder with a role and display name.
    function registerStakeholder(
        address account,
        Role role,
        string calldata name
    ) external onlyAdmin {
        require(role != Role.NONE, "RoleManager: invalid role");
        require(roles[account] == Role.NONE, "RoleManager: already registered");

        roles[account] = role;
        names[account] = name;

        emit RoleGranted(account, role, name);
    }

    /// Returns the role of an address.
    function getRole(address account) external view returns (Role) {
        return roles[account];
    }

    /// Reverts if the address does not hold the expected role.
    function requireRole(address account, Role expected) external view {
        require(roles[account] == expected, "RoleManager: wrong role");
    }
}

